/* ---- sizes ---- */
.hb-sm { --hb-h: 36px; --hl-size: 22px; --hb-pr: 15px; gap: .5em; font-size: 13px; }
.hb-lg { --hb-h: 60px; --hl-size: 38px; --hb-pr: 30px; gap: .8em; font-size: 16px; letter-spacing: .005em; }
.hb-block { display: flex; width: 100%; justify-content: center; }

/* ---- the primary, in ink ---- */
.hb-solid { --hb-paper: var(--ink, #141312); --hb-ink: var(--paper, #f3f0e8); --hb-edge: var(--ink, #141312); color: var(--paper, #f3f0e8); }
@media (hover: hover) {
    .hb-solid:not(:disabled, [aria-disabled=true]):hover {
        --hb-edge: var(--ink, #141312); --hb-paper: color-mix(in srgb, var(--paper, #f3f0e8) 9%, var(--ink, #141312));
    }
}
/* pressed: near-black cannot get much darker, so the ink face lifts a clear step past its hover tone and
   sits inside its ink edge. It reads on a phone (no hover to start from) and under reduced motion (no sink) */
.hb-solid:not(.hb-live):active:not(:disabled, [aria-disabled=true]), .hb-solid.hb-press {
    --hb-face: color-mix(in srgb, var(--paper, #f3f0e8) 17%, var(--ink, #141312)); --hb-edge: var(--ink, #141312);
    box-shadow: inset 0 1px 3px rgba(0, 0, 0, .4);
}
.hb-solid[data-state] { --hb-edge: var(--ink, #141312); }
.hb-solid:focus-visible { outline-color: var(--ink, #141312); }

/* ---- disabled ----
   The disabled attribute (or a disabled fieldset), or an author's aria-disabled at rest (the focusable
   pattern). The word and the drawing go grey and the edge goes faint. Nothing answers a press.
   Both are read at rest only: a button disabled while its job runs keeps its busy and done look, and goes
   grey when it comes back to rest. */
.hb:disabled:not([data-state=waiting], [data-state=working], [data-state=done]),
.hb[aria-disabled=true]:not([data-state=waiting], [data-state=working], [data-state=done]) {
    cursor: default;
    color: var(--ink-3, #8a857d);
    --hb-ink: color-mix(in srgb, var(--ink-3, #8a857d) 78%, var(--hb-face));
    --hb-edge: color-mix(in srgb, var(--rule, #cfcac0) 70%, transparent);
}
.hb-solid:disabled:not([data-state=waiting], [data-state=working], [data-state=done]),
.hb-solid[aria-disabled=true]:not([data-state=waiting], [data-state=working], [data-state=done]) {
    --hb-paper: color-mix(in srgb, var(--ink, #141312) 10%, var(--paper, #f3f0e8));
    --hb-edge: var(--hb-paper);
    --hb-ink: var(--ink-3, #8a857d);
    color: var(--ink-3, #8a857d);
}

@media (prefers-reduced-motion: reduce) {
    .hb, .hb-label, .hb-say, .hb-say.hb-on { transition: none; }
    .hb:not(.hb-live):active:not(:disabled, [aria-disabled=true]), .hb.hb-press { transform: none; }   /* the colour still changes */
}

/* forced colours (Windows high contrast): the drawing in the button's own text colour, on its own face */
@media (forced-colors: active) {
    .hb .hl { --hl-ink: ButtonText; --hl-paper: ButtonFace; }
    .hb:disabled:not([data-state=waiting], [data-state=working], [data-state=done]) .hl { --hl-ink: GrayText; }
}

/* hohmann-loader: an engraved plate of a Hohmann transfer, in one warm ink.
 * Theme with --paper, --paper-2, --ink. Everything is prefixed .hl-.
 * hohmann-button: the original stylesheet with its full-page plate section taken
 * out (that plate and its texture are not part of this folder). Nothing else changed. */

.hl { --hl-paper: var(--paper, #f3f0e8); --hl-ink: var(--ink, #141312); }
.hl-svg { display: block; width: 100%; height: auto; overflow: visible; shape-rendering: geometricPrecision; }
.hl-ink { fill: var(--hl-ink); stroke: none; }
.hl-paper { fill: var(--hl-paper); stroke: none; }
.hl-limb { fill: none; stroke: var(--hl-ink); }
.hl-ring { stroke: var(--hl-ink); }
.hl-orbit { fill: none; stroke: var(--hl-ink); stroke-opacity: .62; }
.hl-plan { fill: none; stroke: var(--hl-ink); stroke-opacity: .7; stroke-linecap: round; }
.hl-mark { fill: none; stroke: var(--hl-ink); stroke-opacity: .7; }

/* ---- the inline loader ------------------------------------------------- */
.hl-inline {
    display: inline-block; vertical-align: -.32em;
    width: var(--hl-size, 1.45em); height: var(--hl-size, 1.45em);
    position: relative;
}
.hl-inline .hl-svg { width: 100%; height: 100%; }
.hl-inline progress {          /* still there for screen readers */
    position: absolute; width: 1px; height: 1px; overflow: hidden;
    clip-path: inset(50%); white-space: nowrap; margin: -1px; border: 0; padding: 0;
}

